function updateRealMap(){if(!window.L)return;let element=$('#realMap'),day=data.days?.[activeMapDay]||data.days?.[0],points=mapStops(day);if(!element||!points.length)return;element.style.display='block';element.previousElementSibling.style.display='none';let center=[points[0].latitude,points[0].longitude];leafletMap=window.L.map(element,{scrollWheelZoom:false,zoomControl:true}).setView(center,13);window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OpenStreetMap</a>'}).addTo(leafletMap);let latlngs=points.map(p=>[Number(p.latitude),Number(p.longitude)]);if(latlngs.length>1)window.L.polyline(latlngs,{color:'#355f4c',weight:4,opacity:.88}).addTo(leafletMap);points.forEach((p,i)=>window.L.circleMarker([p.latitude,p.longitude],{radius:9,color:'#fff',weight:2,fillColor:'#355f4c',fillOpacity:1}).addTo(leafletMap).bindTooltip(`${i+1}. ${esc(p.name)}`));if(latlngs.length>1)leafletMap.fitBounds(latlngs,{padding:[26,26]});requestAnimationFrame(()=>leafletMap?.invalidateSize())}
